def occasions(name, cat=None, price=0):
    o=[]
    if cat=='Restaurants':
        if price>=4: o=['Romantic','Date night']
        elif price==3: o=['Date night']
        elif price==2: o=['Casual','Date night']
        else: o=['Casual']
        if name in ('Zuni Café','Nopa','Foreign Cinema','Che Fico','Flour + Water','Kokkari','Kokkari Estiatorio','Yank Sing','Hong Kong Lounge II','R&G Lounge','China Live','Empress by Boon','Tony\'s Pizza Napoletana','Cheese Board Pizza','Chez Panisse','Ad Hoc','Bouchon','Beretta','Lolinda','Sam\'s Anchor Cafe','Fish.'): o=o+['Group']
    elif cat=='Cafés': o=['Date night','Casual'] if price>=2 else ['Casual']
    elif cat=='Speakeasies': o=['Date night','Late night']
    elif cat=='Bars':
        o=['Late night'] if price<=1 else ['Date night','Late night']
        if 'Brewing' in name or name in ('Toronado','Zeitgeist','Mikkeller Bar','Cellarmaker','Fort Point','Standard Deviant','Harmonic','Barebottle','Woods','Monk\'s Kettle','Rosamunde Sausage Grill','Drake\'s Dealership','Temescal Brewing','Ghost Town Brewing'): o=['Group','Casual']
        if name in ('True Laurel','Pacific Cocktail Haven','Bar Iris','Tonga Room','Top of the Mark','Big 4','Pied Piper','Nightbird\'s Linden Room','Bar Crenn','Ungrafted','Palm City Wines','Absinthe'): o=['Romantic','Date night']
    elif cat=='Rooftops': o=['Date night','Group']
    elif cat=='Coffee': o=['Sweets','Brunch']
    elif cat=='Brunch': o=['Brunch']
    elif cat=='Off-beat': o=['Casual']
    elif cat=='Bakeries': o=['Sweets','Brunch']
    elif cat=='Dessert': o=['Sweets']
    elif cat=='Scene': o=['Group','Date night'] if price<=3 else ['Romantic','Group']
    elif cat=='Nightlife': o=['Late night','Group']
    return o
